1	package com.example.starter.playout;
2	
3	import com.example.starter.playout.PlayoutRepository.DraftRow;
4	import com.example.starter.playout.PlayoutRepository.GrantRow;
5	import com.example.starter.playout.PlayoutRepository.OverrideRow;
6	import com.example.starter.playout.PlayoutRepository.PublicationRow;
7	import com.example.starter.playout.PlayoutRepository.PublicationSegmentRow;
8	import com.example.starter.playout.PlayoutRepository.RequestRow;
9	import com.example.starter.playout.PlayoutRepository.SegmentRow;
10	import com.example.starter.playout.api.ApiException;
11	import com.example.starter.playout.api.Dtos.AssetResponse;
12	import com.example.starter.playout.api.Dtos.ChannelResponse;
13	import com.example.starter.playout.api.Dtos.CreateAssetRequest;
14	import com.example.starter.playout.api.Dtos.CreateChannelRequest;
15	import com.example.starter.playout.api.Dtos.CreateEmergencyOverrideRequest;
16	import com.example.starter.playout.api.Dtos.CreateGrantRequest;
17	import com.example.starter.playout.api.Dtos.DecisionSource;
18	import com.example.starter.playout.api.Dtos.DraftResponse;
19	import com.example.starter.playout.api.Dtos.EmergencyOverrideResponse;
20	import com.example.starter.playout.api.Dtos.FallbackReason;
21	import com.example.starter.playout.api.Dtos.GrantResponse;
22	import com.example.starter.playout.api.Dtos.OverrideStatus;
23	import com.example.starter.playout.api.Dtos.PlayoutDecisionResponse;
24	import com.example.starter.playout.api.Dtos.PublishRequest;
25	import com.example.starter.playout.api.Dtos.PublishResponse;
26	import com.example.starter.playout.api.Dtos.ReplaceDraftRequest;
27	import com.example.starter.playout.api.Dtos.SegmentInput;
28	import com.example.starter.playout.api.Dtos.SegmentResponse;
29	import com.fasterxml.jackson.databind.ObjectMapper;
30	import org.springframework.dao.DuplicateKeyException;
31	import org.springframework.stereotype.Service;
32	import org.springframework.transaction.annotation.Transactional;
33	
34	import java.nio.charset.StandardCharsets;
35	import java.security.MessageDigest;
36	import java.security.NoSuchAlgorithmException;
37	import java.time.Instant;
38	import java.time.LocalDate;
39	import java.time.OffsetDateTime;
40	import java.time.ZoneId;
41	import java.util.ArrayList;
42	import java.util.Comparator;
43	import java.util.List;
44	import java.util.Optional;
45	import java.util.UUID;
46	import java.util.function.Supplier;
47	
48	/**
49	 * 播出编排核心服务：素材、频道、授权、草稿、发布与播出决定。
50	 *
51	 * <p>约定：数据库内时间统一为 UTC 纪元毫秒；API 边界统一为 Asia/Shanghai、毫秒精度 ISO 8601；
52	 * 业务日为 Asia/Shanghai 日历日。授权区间为左闭右开。所有写操作与幂等去重记录在同一事务提交，
53	 * 失败整体回滚、不占用 requestId。</p>
54	 */
55	@Service
56	public class PlayoutService {
57	
58	    /** 业务时区。 */
59	    public static final ZoneId ZONE = ZoneId.of("Asia/Shanghai");
60	
61	    private static final String OP_REPLACE_DRAFT = "REPLACE_DRAFT";
62	    private static final String OP_PUBLISH = "PUBLISH";
63	    private static final String OP_REVOKE_GRANT = "REVOKE_GRANT";
64	    private static final String OP_CREATE_OVERRIDE = "CREATE_OVERRIDE";
65	    private static final String OP_CANCEL_OVERRIDE = "CANCEL_OVERRIDE";
66	
67	    /** 紧急插播时长上限（含）：30 分钟，单位毫秒。 */
68	    private static final long OVERRIDE_MAX_DURATION_MS = 30L * 60L * 1000L;
69	
70	    private final PlayoutRepository repo;
71	    private final ObjectMapper objectMapper;
72	
73	    public PlayoutService(PlayoutRepository repo, ObjectMapper objectMapper) {
74	        this.repo = repo;
75	        this.objectMapper = objectMapper;
76	    }
77	
78	    // ---------- 素材 ----------
79	
80	    /** 创建素材；id 为空时生成稳定 ID。 */
81	    @Transactional
82	    public AssetResponse createAsset(CreateAssetRequest request) {
83	        String id = request.id() == null || request.id().isBlank()
84	                ? UUID.randomUUID().toString() : request.id();
85	        try {
86	            repo.insertAsset(id, request.durationMs(), nowMs());
87	        } catch (DuplicateKeyException e) {
88	            throw ApiException.conflict("DUPLICATE_ID", "素材 ID 已存在: " + id);
89	        }
90	        return new AssetResponse(id, request.durationMs());
91	    }
92	
93	    // ---------- 频道 ----------
94	
95	    /** 创建频道，保底素材必须已存在且不会被撤销。 */
96	    @Transactional
97	    public ChannelResponse createChannel(CreateChannelRequest request) {
98	        String id = request.id() == null || request.id().isBlank()
99	                ? UUID.randomUUID().toString() : request.id();
100	        if (repo.findAsset(request.fallbackAssetId()).isEmpty()) {
101	            throw ApiException.notFound("保底素材不存在: " + request.fallbackAssetId());
102	        }
103	        try {
104	            repo.insertChannel(id, request.fallbackAssetId(), nowMs());
105	        } catch (DuplicateKeyException e) {
106	            throw ApiException.conflict("DUPLICATE_ID", "频道 ID 已存在: " + id);
107	        }
108	        return new ChannelResponse(id, request.fallbackAssetId());
109	    }
110	
111	    // ---------- 授权 ----------
112	
113	    /** 创建授权，关联频道与普通素材，有效区间左闭右开。 */
114	    @Transactional
115	    public GrantResponse createGrant(CreateGrantRequest request) {
116	        var channel = repo.findChannel(request.channelId())
117	                .orElseThrow(() -> ApiException.notFound("频道不存在: " + request.channelId()));
118	        if (repo.findAsset(request.assetId()).isEmpty()) {
119	            throw ApiException.notFound("素材不存在: " + request.assetId());
120	        }
121	        long fromMs = toMs(request.validFrom());
122	        long toMs = toMs(request.validTo());
123	        if (toMs <= fromMs) {
124	            throw ApiException.badRequest("授权有效区间终点必须大于起点");
125	        }
126	        if (channel.fallbackAssetId().equals(request.assetId())) {
127	            throw ApiException.unprocessable("FALLBACK_ASSET_NOT_GRANTABLE",
128	                    "保底素材无需授权，不能对其创建授权");
129	        }
130	        long id = repo.insertGrant(request.channelId(), request.assetId(), fromMs, toMs, nowMs());
131	        return new GrantResponse(id, request.channelId(), request.assetId(),
132	                request.validFrom(), request.validTo(), false);
133	    }
134	
135	    /** 撤销授权；幂等：同 requestId 同参数返回原结果，改参数返回 409。 */
136	    @Transactional
137	    public GrantResponse revokeGrant(long grantId, String requestId) {
138	        String hash = sha256(OP_REVOKE_GRANT + "|" + grantId);
139	        return idempotent(requestId, OP_REVOKE_GRANT, hash, GrantResponse.class, () -> {
140	            GrantRow grant = repo.findGrant(grantId)
141	                    .orElseThrow(() -> ApiException.notFound("授权不存在: " + grantId));
142	            int updated = repo.revokeGrant(grantId, requestId, nowMs());
143	            if (updated == 0) {
144	                throw ApiException.conflict("GRANT_ALREADY_REVOKED", "授权已撤销: " + grantId);
145	            }
146	            return new GrantResponse(grant.id(), grant.channelId(), grant.assetId(),
147	                    atMs(grant.validFromMs()), atMs(grant.validToMs()), true);
148	        });
149	    }
150	
151	    // ---------- 草稿 ----------
152	
153	    /** 整份替换草稿；携带 expectedDraftVersion（0 表示首次创建），版本不符返回 409 且不改写原草稿。 */
154	    @Transactional
155	    public DraftResponse replaceDraft(String channelId, LocalDate businessDay,
156	                                      ReplaceDraftRequest request) {
157	        repo.findChannel(channelId)
158	                .orElseThrow(() -> ApiException.notFound("频道不存在: " + channelId));
159	
160	        String hash = sha256(OP_REPLACE_DRAFT + "|" + channelId + "|" + businessDay
161	                + "|" + request.expectedDraftVersion() + "|" + canonicalSegments(request.segments()));
162	        return idempotent(request.requestId(), OP_REPLACE_DRAFT, hash, DraftResponse.class, () -> {
163	            List<ValidatedSegment> segments = validateSegments(channelId, businessDay, request.segments());
164	            long newVersion;
165	            if (request.expectedDraftVersion() == 0) {
166	                try {
167	                    repo.insertDraft(channelId, businessDay, nowMs());
168	                } catch (DuplicateKeyException e) {
169	                    throw ApiException.conflict("DRAFT_VERSION_CONFLICT",
170	                            "草稿已存在，expectedDraftVersion 不能为 0");
171	                }
172	                newVersion = 1;
173	            } else {
174	                int updated = repo.bumpDraftVersion(channelId, businessDay,
175	                        request.expectedDraftVersion(), nowMs());
176	                if (updated == 0) {
177	                    throw ApiException.conflict("DRAFT_VERSION_CONFLICT",
178	                            "草稿版本不符，期望 " + request.expectedDraftVersion());
179	                }
180	                newVersion = request.expectedDraftVersion() + 1;
181	            }
182	            repo.deleteDraftSegments(channelId, businessDay);
183	            for (ValidatedSegment segment : segments) {
184	                repo.insertDraftSegment(segment.id(), channelId, businessDay,
185	                        segment.assetId(), segment.startMs(), segment.endMs());
186	            }
187	            return new DraftResponse(channelId, businessDay.toString(), newVersion,
188	                    segments.stream().map(ValidatedSegment::toResponse).toList());
189	        });
190	    }
191	
192	    // ---------- 发布 ----------
193	
194	    /**
195	     * 发布草稿：校验草稿版本与发布版本，逐片段加锁校验授权仍有效后原子生成只读快照。
196	     * 与授权撤销并发时按数据库提交顺序生效：撤销先提交则本方法因授权失效而 422 拒绝。
197	     */
198	    @Transactional
199	    public PublishResponse publish(String channelId, LocalDate businessDay, PublishRequest request) {
200	        repo.findChannel(channelId)
201	                .orElseThrow(() -> ApiException.notFound("频道不存在: " + channelId));
202	
203	        String hash = sha256(OP_PUBLISH + "|" + channelId + "|" + businessDay
204	                + "|" + request.draftVersion() + "|" + request.expectedPublishedVersion());
205	        return idempotent(request.requestId(), OP_PUBLISH, hash, PublishResponse.class, () -> {
206	            DraftRow draft = repo.findDraft(channelId, businessDay)
207	                    .orElseThrow(() -> ApiException.notFound("草稿不存在: " + channelId + " " + businessDay));
208	            List<SegmentRow> segments = repo.findDraftSegments(channelId, businessDay);
209	            if (draft.version() != request.draftVersion()) {
210	                throw ApiException.conflict("DRAFT_VERSION_CONFLICT",
211	                        "草稿版本不符，当前 " + draft.version());
212	            }
213	            long currentPublished = repo.currentPublishedVersion(channelId, businessDay);
214	            if (currentPublished != request.expectedPublishedVersion()) {
215	                throw ApiException.conflict("PUBLISHED_VERSION_CONFLICT",
216	                        "发布版本冲突，当前 " + currentPublished);
217	            }
218	            List<Long> grantIds = new ArrayList<>();
219	            for (SegmentRow segment : segments) {
220	                GrantRow grant = selectCoveringGrantForUpdate(channelId, segment);
221	                grantIds.add(grant.id());
222	            }
223	            long newVersion = currentPublished + 1;
224	            long publicationId;
225	            try {
226	                publicationId = repo.insertPublication(channelId, businessDay,
227	                        newVersion, draft.version(), nowMs());
228	            } catch (DuplicateKeyException e) {
229	                throw ApiException.conflict("PUBLISHED_VERSION_CONFLICT",
230	                        "发布版本冲突，版本 " + newVersion + " 已存在");
231	            }
232	            for (int i = 0; i < segments.size(); i++) {
233	                SegmentRow segment = segments.get(i);
234	                repo.insertPublicationSegment(publicationId, segment.id(), segment.assetId(),
235	                        grantIds.get(i), segment.startMs(), segment.endMs());
236	            }
237	            return new PublishResponse(publicationId, channelId, businessDay.toString(),
238	                    newVersion, draft.version());
239	        });
240	    }
241	
242	    // ---------- 播出决定 ----------
243	
244	    /**
245	     * 按频道与时刻查询播出决定。先在命中该时刻的 ACTIVE 紧急插播中选取指定授权当前未撤销的
246	     * 最高优先级插播（EMERGENCY 来源，随附 overrideKey）；高优先级插播授权失效时自动落到
247	     * 仍有效的低优先级插播。无有效插播候选时沿用原节目与保底逻辑。查询不改变插播状态，
248	     * 插播不随授权撤销自动换绑授权。到插播结束时刻（左闭右开）不再命中。
249	     */
250	    @Transactional(readOnly = true)
251	    public PlayoutDecisionResponse playoutDecision(String channelId, OffsetDateTime at) {
252	        var channel = repo.findChannel(channelId)
253	                .orElseThrow(() -> ApiException.notFound("频道不存在: " + channelId));
254	        long atMs = toMs(at);
255	
256	        Optional<OverrideRow> override = selectActiveOverrideAt(channelId, atMs);
257	        if (override.isPresent()) {
258	            OverrideRow hit = override.get();
259	            return new PlayoutDecisionResponse(channelId, at, hit.assetId(),
260	                    DecisionSource.EMERGENCY, null, null, null, hit.overrideKey());
261	        }
262	
263	        LocalDate businessDay = at.atZoneSameInstant(ZONE).toLocalDate();
264	
265	        Optional<PublicationRow> publication = repo.findLatestPublication(channelId, businessDay);
266	        if (publication.isEmpty()) {
267	            return fallback(channelId, at, channel.fallbackAssetId(),
268	                    FallbackReason.NO_PUBLISHED_SCHEDULE);
269	        }
270	        Optional<PublicationSegmentRow> segment =
271	                repo.findPublicationSegmentAt(publication.get().id(), atMs);
272	        if (segment.isEmpty()) {
273	            return fallback(channelId, at, channel.fallbackAssetId(),
274	                    FallbackReason.GAP);
275	        }
276	        PublicationSegmentRow hit = segment.get();
277	        GrantRow grant = repo.findGrant(hit.grantId())
278	                .orElseThrow(() -> ApiException.unprocessable("SNAPSHOT_INCOMPLETE",
279	                        "发布快照引用的授权不存在: " + hit.grantId()));
280	        if (grant.revoked()) {
281	            return new PlayoutDecisionResponse(channelId, at, channel.fallbackAssetId(),
282	                    DecisionSource.FALLBACK,
283	                    FallbackReason.GRANT_REVOKED,
284	                    publication.get().id(), hit.segmentId(), null);
285	        }
286	        return new PlayoutDecisionResponse(channelId, at, hit.assetId(),
287	                DecisionSource.PROGRAM, null,
288	                publication.get().id(), hit.segmentId(), null);
289	    }
290	
291	    /**
292	     * 选取某时刻生效的最高优先级紧急插播：候选为区间命中且 ACTIVE 的插播，按优先级降序，
293	     * 跳过其指定授权已撤销的插播。授权状态为查询时的实时状态。
294	     */
295	    private Optional<OverrideRow> selectActiveOverrideAt(String channelId, long atMs) {
296	        for (OverrideRow candidate : repo.findActiveOverridesAt(channelId, atMs)) {
297	            GrantRow grant = repo.findGrant(candidate.grantId()).orElse(null);
298	            if (grant != null && !grant.revoked()) {
299	                return Optional.of(candidate);
300	            }
301	        }
302	        return Optional.empty();
303	    }
304	
305	    // ---------- 紧急插播 ----------
306	
307	    /**
308	     * 创建限时紧急插播：创建即 ACTIVE，只可取消不可改写。校验频道/素材/授权存在、授权属于该
309	     * 频道与素材且未撤销并完整覆盖区间、区间同日且时长在 (0, 30 分钟]；同频道同优先级 ACTIVE
310	     * 区间不得重叠（相邻合法）。携带 requestId 幂等：同键同参返回首次结果，改参 409，失败不占键；
311	     * 已取消插播不能用相同 overrideKey 重放复活。
312	     */
313	    @Transactional
314	    public EmergencyOverrideResponse createEmergencyOverride(CreateEmergencyOverrideRequest request) {
315	        String hash = sha256(OP_CREATE_OVERRIDE + "|" + request.overrideKey() + "|"
316	                + request.channelId() + "|" + request.assetId() + "|" + request.grantId() + "|"
317	                + request.priority() + "|" + toMs(request.start()) + "|" + toMs(request.end()));
318	        return idempotent(request.requestId(), OP_CREATE_OVERRIDE, hash,
319	                EmergencyOverrideResponse.class, () -> doCreateOverride(request));
320	    }
321	
322	    private EmergencyOverrideResponse doCreateOverride(CreateEmergencyOverrideRequest request) {
323	        long startMs = toMs(request.start());
324	        long endMs = toMs(request.end());
325	        long durationMs = endMs - startMs;
326	        if (durationMs <= 0) {
327	            throw ApiException.badRequest("紧急插播结束时间必须大于开始时间");
328	        }
329	        if (durationMs > OVERRIDE_MAX_DURATION_MS) {
330	            throw ApiException.badRequest("紧急插播时长不得超过 30 分钟");
331	        }
332	        LocalDate startDay = request.start().atZoneSameInstant(ZONE).toLocalDate();
333	        LocalDate endDay = request.end().atZoneSameInstant(ZONE).toLocalDate();
334	        if (!startDay.equals(endDay)) {
335	            throw ApiException.badRequest("紧急插播起止时间必须处于同一 Asia/Shanghai 业务日");
336	        }
337	
338	        repo.lockChannelForUpdate(request.channelId());
339	        var channel = repo.findChannel(request.channelId())
340	                .orElseThrow(() -> ApiException.notFound("频道不存在: " + request.channelId()));
341	        if (repo.findAsset(request.assetId()).isEmpty()) {
342	            throw ApiException.notFound("素材不存在: " + request.assetId());
343	        }
344	        if (channel.fallbackAssetId().equals(request.assetId())) {
345	            throw ApiException.unprocessable("FALLBACK_ASSET_NOT_GRANTABLE",
346	                    "保底素材不得用于紧急插播");
347	        }
348	
349	        // 同键语义：已存在（含已取消）即冲突，重放创建不能复活已取消插播。
350	        if (repo.findOverrideForUpdate(request.overrideKey()).isPresent()) {
351	            throw ApiException.conflict("DUPLICATE_OVERRIDE_KEY",
352	                    "紧急插播 overrideKey 已存在: " + request.overrideKey());
353	        }
354	
355	        // 锁定授权行：与撤销事务按提交顺序串行。撤销先提交时 revoked=1，此处 422 拒绝。
356	        GrantRow grant = repo.findGrantForUpdate(request.grantId())
357	                .orElseThrow(() -> ApiException.notFound("授权不存在: " + request.grantId()));
358	        if (!grant.channelId().equals(request.channelId()) || !grant.assetId().equals(request.assetId())) {
359	            throw ApiException.unprocessable("GRANT_NOT_MATCHED",
360	                    "指定授权不属于该频道或素材: " + request.grantId());
361	        }
362	        if (grant.revoked()) {
363	            throw ApiException.unprocessable("GRANT_INVALID",
364	                    "指定授权已撤销: " + request.grantId());
365	        }
366	        if (grant.validFromMs() > startMs || grant.validToMs() < endMs) {
367	            throw ApiException.unprocessable("GRANT_NOT_COVERING",
368	                    "指定授权未完整覆盖插播区间: " + request.grantId());
369	        }
370	
371	        List<OverrideRow> overlapping = repo.findActiveOverlappingForUpdate(
372	                request.channelId(), request.priority(), startMs, endMs);
373	        if (!overlapping.isEmpty()) {
374	            throw ApiException.conflict("OVERRIDE_INTERVAL_CONFLICT",
375	                    "同频道同优先级 ACTIVE 插播区间重叠: " + overlapping.get(0).overrideKey());
376	        }
377	
378	        long createdAtMs = nowMs();
379	        try {
380	            repo.insertOverride(request.overrideKey(), request.channelId(), request.assetId(),
381	                    request.grantId(), request.priority(), startMs, endMs, startDay, createdAtMs);
382	        } catch (DuplicateKeyException e) {
383	            throw ApiException.conflict("DUPLICATE_OVERRIDE_KEY",
384	                    "紧急插播 overrideKey 已存在: " + request.overrideKey());
385	        }
386	        return new EmergencyOverrideResponse(request.overrideKey(), request.channelId(),
387	                request.assetId(), request.grantId(), request.priority(),
388	                request.start(), request.end(), OverrideStatus.ACTIVE, null, null,
389	                atMs(createdAtMs));
390	    }
391	
392	    /**
393	     * 取消紧急插播：仅 ACTIVE 可取消，已取消再取消为 409 状态冲突；取消提交后释放同优先级
394	     * 冲突区间。携带 requestId 幂等：同键同参返回首次结果（含 CANCELLED 明细），改参 409，
395	     * 失败不占键。
396	     */
397	    @Transactional
398	    public EmergencyOverrideResponse cancelEmergencyOverride(String overrideKey, String requestId) {
399	        String hash = sha256(OP_CANCEL_OVERRIDE + "|" + overrideKey);
400	        return idempotent(requestId, OP_CANCEL_OVERRIDE, hash, EmergencyOverrideResponse.class, () -> {
401	            // 先在频道锁上与同频道创建/取消串行，取消提交后并发创建即可复用该区间。
402	            OverrideRow existing = repo.findOverride(overrideKey)
403	                    .orElseThrow(() -> ApiException.notFound("紧急插播不存在: " + overrideKey));
404	            repo.lockChannelForUpdate(existing.channelId());
405	            int updated = repo.cancelOverride(overrideKey, requestId, nowMs());
406	            if (updated == 0) {
407	                throw ApiException.conflict("OVERRIDE_NOT_ACTIVE",
408	                        "紧急插播已取消，不能重复取消: " + overrideKey);
409	            }
410	            return toOverrideResponse(repo.findOverrideForUpdate(overrideKey).orElseThrow());
411	        });
412	    }
413	
414	    /** 查询紧急插播明细（不做状态校验，ACTIVE/CANCELLED 均返回，含取消情况与原授权关联）。 */
415	    @Transactional(readOnly = true)
416	    public EmergencyOverrideResponse getEmergencyOverride(String overrideKey) {
417	        OverrideRow row = repo.findOverride(overrideKey)
418	                .orElseThrow(() -> ApiException.notFound("紧急插播不存在: " + overrideKey));
419	        return toOverrideResponse(row);
420	    }
421	
422	    private static EmergencyOverrideResponse toOverrideResponse(OverrideRow row) {
423	        return new EmergencyOverrideResponse(row.overrideKey(), row.channelId(), row.assetId(),
424	                row.grantId(), row.priority(), atMs(row.startMs()), atMs(row.endMs()),
425	                row.active() ? OverrideStatus.ACTIVE : OverrideStatus.CANCELLED,
426	                row.cancelRequestId(),
427	                row.cancelledAtMs() == null ? null : atMs(row.cancelledAtMs()),
428	                atMs(row.createdAtMs()));
429	    }
430	
431	    // ---------- 内部方法 ----------
432	
433	    /** 校验并规范化草稿片段：非空、区间内、不跨日、不重叠、素材存在且被单条未撤销授权完整覆盖。 */
434	    private List<ValidatedSegment> validateSegments(String channelId, LocalDate businessDay,
435	                                                    List<SegmentInput> inputs) {
436	        long dayStartMs = businessDay.atStartOfDay(ZONE).toInstant().toEpochMilli();
437	        long dayEndMs = businessDay.plusDays(1).atStartOfDay(ZONE).toInstant().toEpochMilli();
438	
439	        List<ValidatedSegment> segments = new ArrayList<>();
440	        for (SegmentInput input : inputs) {
441	            if (input.start() == null || input.end() == null) {
442	                throw ApiException.badRequest("片段开始与结束时间不能为空");
443	            }
444	            if (input.assetId() == null || input.assetId().isBlank()) {
445	                throw ApiException.badRequest("片段素材 ID 不能为空");
446	            }
447	            long startMs = toMs(input.start());
448	            long endMs = toMs(input.end());
449	            if (endMs <= startMs) {
450	                throw ApiException.badRequest("片段结束时间必须大于开始时间");
451	            }
452	            if (startMs < dayStartMs || endMs > dayEndMs) {
453	                throw ApiException.unprocessable("SEGMENT_CROSSES_DAY",
454	                        "片段不得跨业务日: " + input.start() + " ~ " + input.end());
455	            }
456	            String id = input.id() == null || input.id().isBlank()
457	                    ? UUID.randomUUID().toString() : input.id();
458	            segments.add(new ValidatedSegment(id, input.assetId(), startMs, endMs));
459	        }
460	
461	        List<ValidatedSegment> sorted = segments.stream()
462	                .sorted(Comparator.comparingLong(ValidatedSegment::startMs)
463	                        .thenComparing(ValidatedSegment::id))
464	                .toList();
465	        for (int i = 1; i < sorted.size(); i++) {
466	            if (sorted.get(i).startMs() < sorted.get(i - 1).endMs()) {
467	                throw ApiException.unprocessable("SEGMENT_OVERLAP",
468	                        "片段时间重叠: " + sorted.get(i - 1).id() + " 与 " + sorted.get(i).id());
469	            }
470	        }
471	
472	        for (ValidatedSegment segment : segments) {
473	            if (repo.findAsset(segment.assetId()).isEmpty()) {
474	                throw ApiException.notFound("素材不存在: " + segment.assetId());
475	            }
476	            List<GrantRow> covering = repo.findCoveringGrants(channelId, segment.assetId(),
477	                    segment.startMs(), segment.endMs());
478	            if (covering.isEmpty()) {
479	                throw ApiException.unprocessable("NO_COVERING_GRANT",
480	                        "片段未被单条有效授权完整覆盖: " + segment.id());
481	            }
482	        }
483	        return segments;
484	    }
485	
486	    /** 发布时加行锁选取覆盖授权；不存在或未撤销的覆盖授权时 422 拒绝整次发布。 */
487	    private GrantRow selectCoveringGrantForUpdate(String channelId, SegmentRow segment) {
488	        List<GrantRow> candidates = repo.findCoveringGrantsForUpdate(channelId, segment.assetId(),
489	                segment.startMs(), segment.endMs());
490	        return candidates.stream()
491	                .filter(grant -> !grant.revoked())
492	                .findFirst()
493	                .orElseThrow(() -> ApiException.unprocessable("GRANT_INVALID",
494	                        "片段授权已失效，发布拒绝: " + segment.id()));
495	    }
496	
497	    /**
498	     * 幂等执行：去重记录与业务结果同事务提交；同 requestId 同参数返回原结果，
499	     * 同 requestId 不同参数返回 409；业务失败抛异常回滚，不占用 requestId。
500	     */
501	    private <T> T idempotent(String requestId, String operation, String paramsHash,
502	                             Class<T> type, Supplier<T> action) {
503	        if (requestId == null || requestId.isBlank()) {
504	            throw ApiException.badRequest("requestId 不能为空");
505	        }
506	        Optional<RequestRow> existing = repo.findRequestForUpdate(requestId);
507	        if (existing.isPresent()) {
508	            return replay(existing.get(), operation, paramsHash, type);
509	        }
510	        try {
511	            repo.insertRequest(requestId, operation, paramsHash, nowMs());
512	        } catch (DuplicateKeyException e) {
513	            // 并发同 requestId：等待对方事务结束后读取已提交记录
514	            RequestRow committed = repo.findRequestForUpdate(requestId)
515	                    .orElseThrow(() -> ApiException.conflict("REQUEST_ID_CONFLICT",
516	                            "requestId 并发冲突: " + requestId));
517	            return replay(committed, operation, paramsHash, type);
518	        }
519	        T result = action.get();
520	        try {
521	            repo.completeRequest(requestId, objectMapper.writeValueAsString(result));
522	        } catch (Exception e) {
523	            throw new IllegalStateException("幂等结果序列化失败", e);
524	        }
525	        return result;
526	    }
527	
528	    private <T> T replay(RequestRow row, String operation, String paramsHash, Class<T> type) {
529	        if (!row.operation().equals(operation) || !row.paramsHash().equals(paramsHash)) {
530	            throw ApiException.conflict("REQUEST_ID_CONFLICT",
531	                    "requestId 已使用且参数不一致: " + row.requestId());
532	        }
533	        if (row.responseBody() == null) {
534	            throw ApiException.conflict("REQUEST_ID_CONFLICT",
535	                    "requestId 请求尚未完成: " + row.requestId());
536	        }
537	        try {
538	            return objectMapper.readValue(row.responseBody(), type);
539	        } catch (Exception e) {
540	            throw new IllegalStateException("幂等结果反序列化失败", e);
541	        }
542	    }
543	
544	    private static String canonicalSegments(List<SegmentInput> segments) {
545	        StringBuilder sb = new StringBuilder();
546	        for (SegmentInput s : segments) {
547	            sb.append(s.id() == null ? "" : s.id()).append(',')
548	                    .append(s.assetId()).append(',')
549	                    .append(s.start() == null ? "" : toMs(s.start())).append(',')
550	                    .append(s.end() == null ? "" : toMs(s.end())).append(';');
551	        }
552	        return sb.toString();
553	    }
554	
555	    private PlayoutDecisionResponse fallback(String channelId, OffsetDateTime at, String assetId,
556	                                             FallbackReason reason) {
557	        return new PlayoutDecisionResponse(channelId, at, assetId,
558	                DecisionSource.FALLBACK, reason, null, null, null);
559	    }
560	
561	    private static long toMs(OffsetDateTime time) {
562	        return time.toInstant().toEpochMilli();
563	    }
564	
565	    private static OffsetDateTime atMs(long epochMs) {
566	        return OffsetDateTime.ofInstant(Instant.ofEpochMilli(epochMs), ZONE);
567	    }
568	
569	    private static long nowMs() {
570	        return System.currentTimeMillis();
571	    }
572	
573	    private static String sha256(String text) {
574	        try {
575	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
576	            byte[] hash = digest.digest(text.getBytes(StandardCharsets.UTF_8));
577	            StringBuilder sb = new StringBuilder(hash.length * 2);
578	            for (byte b : hash) {
579	                sb.append(Character.forDigit((b >> 4) & 0xF, 16));
580	                sb.append(Character.forDigit(b & 0xF, 16));
581	            }
582	            return sb.toString();
583	        } catch (NoSuchAlgorithmException e) {
584	            throw new IllegalStateException(e);
585	        }
586	    }
587	
588	    /** 校验后的片段。 */
589	    private record ValidatedSegment(String id, String assetId, long startMs, long endMs) {
590	        SegmentResponse toResponse() {
591	            return new SegmentResponse(id, assetId, atMs(startMs), atMs(endMs));
592	        }
593	    }
594	}
