3	import com.example.starter.playout.PlayoutService;
4	import com.example.starter.playout.api.Dtos.AssetResponse;
5	import com.example.starter.playout.api.Dtos.ChannelResponse;
6	import com.example.starter.playout.api.Dtos.CreateAssetRequest;
7	import com.example.starter.playout.api.Dtos.CreateChannelRequest;
8	import com.example.starter.playout.api.Dtos.CreateEmergencyOverrideRequest;
9	import com.example.starter.playout.api.Dtos.CreateGrantRequest;
10	import com.example.starter.playout.api.Dtos.DraftResponse;
11	import com.example.starter.playout.api.Dtos.EmergencyOverrideResponse;
12	import com.example.starter.playout.api.Dtos.GrantResponse;
13	import com.example.starter.playout.api.Dtos.CancelEmergencyOverrideRequest;
14	import com.example.starter.playout.api.Dtos.PlayoutDecisionResponse;
15	import com.example.starter.playout.api.Dtos.PublishRequest;
16	import com.example.starter.playout.api.Dtos.PublishResponse;
17	import com.example.starter.playout.api.Dtos.ReplaceDraftRequest;
18	import com.example.starter.playout.api.Dtos.RevokeGrantRequest;
19	import jakarta.validation.Valid;
20	import jakarta.validation.constraints.NotBlank;
21	import org.springframework.format.annotation.DateTimeFormat;
22	import org.springframework.validation.annotation.Validated;
23	import org.springframework.web.bind.annotation.GetMapping;
24	import org.springframework.web.bind.annotation.PathVariable;
25	import org.springframework.web.bind.annotation.PostMapping;
26	import org.springframework.web.bind.annotation.PutMapping;
27	import org.springframework.web.bind.annotation.RequestBody;
28	import org.springframework.web.bind.annotation.RequestMapping;
29	import org.springframework.web.bind.annotation.RequestParam;
30	import org.springframework.web.bind.annotation.RestController;
31	
32	import java.time.LocalDate;
33	import java.time.OffsetDateTime;
34	import java.time.format.DateTimeParseException;
35	
36	/**
37	 * 播出编排 REST API。成功响应统一 200；错误区分 400 参数错误、404 资源不存在、
38	 * 409 版本/幂等冲突、422 业务规则不满足。
39	 */
40	@Validated
41	@RestController
42	@RequestMapping("/api")
43	public class PlayoutController {
44	
45	    private final PlayoutService service;
46	
47	    public PlayoutController(PlayoutService service) {
48	        this.service = service;
49	    }
50	
51	    /** 创建素材。 */
52	    @PostMapping("/assets")
53	    public AssetResponse createAsset(@Valid @RequestBody CreateAssetRequest request) {
54	        return service.createAsset(request);
55	    }
56	
57	    /** 创建频道。 */
58	    @PostMapping("/channels")
59	    public ChannelResponse createChannel(@Valid @RequestBody CreateChannelRequest request) {
60	        return service.createChannel(request);
61	    }
62	
63	    /** 创建授权。 */
64	    @PostMapping("/grants")
65	    public GrantResponse createGrant(@Valid @RequestBody CreateGrantRequest request) {
66	        return service.createGrant(request);
67	    }
68	
69	    /** 撤销授权（幂等）。 */
70	    @PostMapping("/grants/{grantId}/revoke")
71	    public GrantResponse revokeGrant(@PathVariable long grantId,
72	                                     @Valid @RequestBody RevokeGrantRequest request) {
73	        return service.revokeGrant(grantId, request.requestId());
74	    }
75	
76	    /** 整份替换频道某业务日草稿（乐观锁 + 幂等）。 */
77	    @PutMapping("/channels/{channelId}/drafts/{businessDay}")
78	    public DraftResponse replaceDraft(@PathVariable @NotBlank String channelId,
79	                                      @PathVariable String businessDay,
80	                                      @Valid @RequestBody ReplaceDraftRequest request) {
81	        return service.replaceDraft(channelId, parseBusinessDay(businessDay), request);
82	    }
83	
84	    /** 发布频道某业务日草稿（乐观锁 + 幂等）。 */
85	    @PostMapping("/channels/{channelId}/drafts/{businessDay}/publish")
86	    public PublishResponse publish(@PathVariable @NotBlank String channelId,
87	                                   @PathVariable String businessDay,
88	                                   @Valid @RequestBody PublishRequest request) {
89	        return service.publish(channelId, parseBusinessDay(businessDay), request);
90	    }
91	
92	    /** 按频道与时刻查询播出决定。 */
93	    @GetMapping("/channels/{channelId}/playout")
94	    public PlayoutDecisionResponse playout(@PathVariable @NotBlank String channelId,
95	                                           @RequestParam
96	                                           @DateTimeFormat(iso = DateTimeFormat.ISO.DATE_TIME)
97	                                           OffsetDateTime at) {
98	        return service.playoutDecision(channelId, at);
99	    }
100	
101	    /** 创建限时紧急插播（创建即 ACTIVE，携带 requestId 幂等）。 */
102	    @PostMapping("/emergency-overrides")
103	    public EmergencyOverrideResponse createEmergencyOverride(
104	            @Valid @RequestBody CreateEmergencyOverrideRequest request) {
105	        return service.createEmergencyOverride(request);
106	    }
107	
108	    /** 取消紧急插播（仅 ACTIVE 可取消，携带 requestId 幂等）。 */
109	    @PostMapping("/emergency-overrides/{overrideKey}/cancel")
110	    public EmergencyOverrideResponse cancelEmergencyOverride(
111	            @PathVariable @NotBlank String overrideKey,
112	            @Valid @RequestBody CancelEmergencyOverrideRequest request) {
113	        return service.cancelEmergencyOverride(overrideKey, request.requestId());
114	    }
115	
116	    /** 查询紧急插播明细，ACTIVE/CANCELLED 均返回，保留取消情况与原授权关联。 */
117	    @GetMapping("/emergency-overrides/{overrideKey}")
118	    public EmergencyOverrideResponse emergencyOverride(@PathVariable @NotBlank String overrideKey) {
119	        return service.getEmergencyOverride(overrideKey);
120	    }
121	
122	    private static LocalDate parseBusinessDay(String businessDay) {
123	        try {
124	            return LocalDate.parse(businessDay);
125	        } catch (DateTimeParseException e) {
126	            throw ApiException.badRequest("业务日格式应为 yyyy-MM-dd: " + businessDay);
127	        }
128	    }
129	}
