        playout(ctx, "2026-09-22T10:10:00.000+08:00")
                .andExpect(jsonPath("$.source").value("PROGRAM"))
                .andExpect(jsonPath("$.assetId").value(ctx.movieAsset));
        // 区间内：EMERGENCY 优先于已发布节目，返回素材与 overrideKey

