428	        CountDownLatch ready = new CountDownLatch(2);
429	        CountDownLatch start = new CountDownLatch(1);
430	        ExecutorService pool = Executors.newFixedThreadPool(2);
431	        try {
432	            Future<Integer> createFuture = pool.submit(() -> {
433	                ready.countDown();
434	                start.await(5, TimeUnit.SECONDS);
435	                return mvc.perform(post("/api/emergency-overrides")
436	                                .contentType(MediaType.APPLICATION_JSON)
437	                                .content(objectMapper.writeValueAsString(overrideBody(
